import { readFileSync,writeFileSync,mkdirSync,existsSync,statfsSync,readdirSync,lstatSync,copyFileSync,unlinkSync } from 'node:fs';
import { join,resolve,relative } from 'node:path';
import { createHash } from 'node:crypto';
import { createOwnedTestDirectory } from '../tests/helpers/owned-test-directory';
import { discoverInventory,sourceHash } from '../scripts/quality-inventory';
import { OwnedDatabase } from '../src/infrastructure/database/owned-database';
import { createSchema } from '../src/infrastructure/database/schema';
import { MemoryEventEnvelope } from '../src/domain/entities/memory-event';
const root=process.cwd(),initial=statfsSync(root),initialFree=initial.bavail*initial.bsize;
assert(initialFree>7*1073741824,'Need 7GiB headroom for bounded isolated install');
const storage=createOwnedTestDirectory('memory-package-boundary-'),stage=join(storage.dir,'package'),consumer=join(storage.dir,'consumer'),cache=join(storage.dir,'cache');
for(const path of [stage,consumer,cache])mkdirSync(path);
const sha=(value:Buffer|string)=>createHash('sha256').update(value).digest('hex');
const sourceInputs=discoverInventory(root).files.map(f=>({path:f.path,sourceHash:f.sourceHash}));
for(const path of ['package.json','bun.lock','tsconfig.json','tsconfig.lib.json'])sourceInputs.push({path,sourceHash:sourceHash(readFileSync(path,'utf8'))});
const report:any={recordedAt:new Date().toISOString(),startingRevision:'18e5f79909824f1029ff2475e7f6229edf664413 + source-bound hook repair',runtime:Bun.version,cwd:root,sourceInputs,initialFreeBytes:initialFree,runs:[],fixtures:[]};
function env(home:string){return {...process.env,HOME:home,USERPROFILE:home,XDG_DATA_HOME:join(home,'data'),XDG_CONFIG_HOME:join(home,'config'),XDG_CACHE_HOME:cache,MEMORY_HOME:join(home,'authored'),CLAUDE_CONFIG_DIR:join(home,'claude'),BUN_INSTALL:join(storage.dir,'bun'),BUN_INSTALL_CACHE_DIR:cache,NPM_CONFIG_CACHE:join(cache,'npm'),APPDATA:join(home,'appdata'),LOCALAPPDATA:join(home,'localappdata'),TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir};}
async function run(label:string,command:string[],cwd:string,home:string,timeout=120000,input?:string){
 const startedAt=new Date().toISOString(),child=Bun.spawn(command,{cwd,env:env(home),stdin:input===undefined?'ignore':Buffer.from(input),stdout:'pipe',stderr:'pipe'});
 let terminal=false,stopReason:string|undefined,minFree=initialFree;
 const deadline=Date.now()+timeout;
 const monitor=(async()=>{while(!terminal){const disk=statfsSync(root),free=disk.bavail*disk.bsize;minFree=Math.min(minFree,free);if(free<4*1073741824||initialFree-free>3*1073741824||Date.now()>deadline){stopReason=Date.now()>deadline?'time limit':'disk guard';child.kill();break;}await Bun.sleep(250);}})();
 const [exit,stdout,stderr]=await Promise.all([child.exited,new Response(child.stdout).text(),new Response(child.stderr).text()]);terminal=true;await monitor;
 const row={label,command,cwd,startedAt,finishedAt:new Date().toISOString(),exit,stopReason,minFreeBytes:minFree,output:stdout+stderr};report.runs.push(row);writeFileSync('.git/d05-package-consumer-progress.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({label,exit,stopReason}));return row;
}
function listFiles(dir:string,prefix=''):Array<{path:string,sha256:string,bytes:number}>{return readdirSync(join(dir,prefix)).flatMap(name=>{const path=join(prefix,name),stat=lstatSync(join(dir,path));assert(!stat.isSymbolicLink(),'Packaged file must not be a link');return stat.isDirectory()?listFiles(dir,path):[{path:path.replaceAll('\\','/'),sha256:sha(readFileSync(join(dir,path))),bytes:stat.size}];});}
try{
 for(const file of ['package.json','README.md','LICENSE'])if(existsSync(file))copyFileSync(file,join(stage,file));
 for(const [label,command] of [
  ['declarations',[process.execPath,resolve('node_modules/typescript/bin/tsc'),'--project','tsconfig.lib.json','--outDir',join(stage,'dist')]],
  ['library',[process.execPath,'build','src/index.ts','--outdir',join(stage,'dist'),'--target','bun','--packages=external','--minify','--sourcemap=none']],
  ['hook',[process.execPath,'build','src/infrastructure/hooks/sync-hook-script.ts','--outfile='+join(stage,'dist','sync-hook.js'),'--target=bun']],
  ['cli',[process.execPath,'build','src/presentation/cli/index.ts','--outdir',join(stage,'dist','presentation','cli'),'--target','bun','--packages=external','--minify','--sourcemap=none']],
 ] as const){const result=await run(label,[...command],root,storage.dir);assert.equal(result.exit,0,label);}
 const artifact=join(storage.dir,'memory-candidate.tgz');
 const packed=await run('pack',[process.execPath,'pm','pack','--ignore-scripts','--filename',artifact],stage,storage.dir);assert.equal(packed.exit,0);assert(existsSync(artifact));
 report.artifact={path:artifact,sha256:sha(readFileSync(artifact)),bytes:lstatSync(artifact).size,files:listFiles(stage)};
 writeFileSync(join(consumer,'package.json'),JSON.stringify({name:'memory-synthetic-consumer',private:true,type:'module',dependencies:{'@chude/memory':'file:'+artifact.replaceAll('\\','/')}}));
 const locked=await run('resolve-lock',[process.execPath,'install','--lockfile-only','--save-text-lockfile','--ignore-scripts','--cache-dir',cache],consumer,consumer,300000);assert.equal(locked.exit,0,'dependency resolution');
 report.consumerFilesAfterResolution=readdirSync(consumer);assert(existsSync(join(consumer,'bun.lock')),'Text lockfile must exist before install');
 const installed=await run('install',[process.execPath,'install','--production','--frozen-lockfile','--ignore-scripts','--cache-dir',cache],consumer,consumer,300000);assert.equal(installed.exit,0,'isolated install');
 const installedRoot=join(consumer,'node_modules','@chude','memory');
 const packageFiles=report.artifact.files.map((f:any)=>({...f,installedExists:existsSync(join(installedRoot,f.path)),installedHash:existsSync(join(installedRoot,f.path))?sha(readFileSync(join(installedRoot,f.path))):null}));assert(packageFiles.every((f:any)=>f.sha256===f.installedHash));report.installed={root:installedRoot,files:packageFiles,lock:readFileSync(join(consumer,'bun.lock'),'utf8')};
 const shim=join(consumer,'node_modules','.bin','memory.exe');assert(existsSync(shim));report.installed.shim={path:shim,sha256:sha(readFileSync(shim))};
 const libraryProbe=join(consumer,'library-check.ts');writeFileSync(libraryProbe,"import { executeProjectionsRebuildCommand, executeBackupCreateCommand } from '@chude/memory';\nconsole.log(JSON.stringify({resolved:import.meta.resolve('@chude/memory'),projection:typeof executeProjectionsRebuildCommand,backup:typeof executeBackupCreateCommand}));\n");
 const library=await run('installed-library',[process.execPath,libraryProbe],consumer,consumer);assert.equal(library.exit,0);report.library=JSON.parse(library.output);assert(report.library.resolved.includes('/node_modules/@chude/memory/'));assert.equal(report.library.projection,'function');

 const home=join(storage.dir,'hook-home'),cwd=join(storage.dir,'unrelated-hook-cwd');mkdirSync(join(home,'.claude'),{recursive:true});mkdirSync(join(cwd,'dist'),{recursive:true});
 writeFileSync(join(home,'.claude','settings.json'),JSON.stringify({fixture:'preserved'}));writeFileSync(join(cwd,'dist','sync-hook.js'),'throw new Error("unrelated decoy");');
 const installHook=await run('installed-hook-install',[shim,'install'],cwd,home);assert.equal(installHook.exit,0);
 const copied=join(home,'data','memory','hooks','sync-hook.js'),packagedHook=join(installedRoot,'dist','sync-hook.js');assert.equal(sha(readFileSync(copied)),sha(readFileSync(packagedHook)));
 const settings=JSON.parse(readFileSync(join(home,'.claude','settings.json'),'utf8'));assert.equal(settings.fixture,'preserved');assert.equal(settings.hooks.SessionEnd[0].hooks[0].command,'bun run "'+copied.replaceAll('\\','/')+'"');
 const executedHook=await run('installed-hook-execute',[process.execPath,'run',copied],cwd,home,30000,JSON.stringify({hook_event_name:'PreCompact'}));assert.equal(executedHook.exit,0);assert(executedHook.output.includes('MEMORY FLUSH'));
 const log=readFileSync(join(home,'data','memory','logs','sync.log'),'utf8');assert(log.includes('No session_id in PreCompact hook input'));
 const libraryInstaller=join(consumer,'library-install.ts');writeFileSync(libraryInstaller,"import {executeInstallCommand} from '@chude/memory';process.exitCode=(await executeInstallCommand({force:true})).exitCode;");
 const libraryInstall=await run('installed-library-hook-install',[process.execPath,libraryInstaller],cwd,home);assert.equal(libraryInstall.exit,0);assert.equal(sha(readFileSync(copied)),sha(readFileSync(packagedHook)));
 unlinkSync(copied);const repair=await run('installed-hook-missing-file-repair',[shim,'install'],cwd,home);assert.equal(repair.exit,0);assert.equal(sha(readFileSync(copied)),sha(readFileSync(packagedHook)));
 const removed=await run('installed-hook-uninstall',[shim,'uninstall'],cwd,home);assert.equal(removed.exit,0);assert(!existsSync(copied));const afterSettings=JSON.parse(readFileSync(join(home,'.claude','settings.json'),'utf8'));assert.equal(afterSettings.fixture,'preserved');assert.equal(afterSettings.hooks?.SessionEnd,undefined);
 report.hook={packagedSha256:sha(readFileSync(packagedHook)),settingsPreserved:true,decoyIgnored:true,missingFileRepaired:true,uninstalled:true,execution:'Actual copied hook: PreCompact reminder and missing-session warning. No background sync/provider/remote requested.'};
 const time='2026-09-28T10:00:00.000Z';
 const wrapper=MemoryEventEnvelope.create({eventId:'synthetic-batch',machineId:'synthetic',sequence:30,kind:'projection',operation:'add',occurredAt:new Date(time),observedAt:new Date(time),scope:{project:'synthetic',visibility:'project'},provenance:{source:'memory-extraction',actor:'memory',method:'extraction-batch-v1',sourceIds:['synthetic-session']},privacy:{redactionState:'redacted',containsSensitiveContent:false},consent:{status:'denied',scopes:['local']},causality:{parentEventIds:[],relatedEventIds:[],supersedesEventIds:[]},payload:{extractionBatch:{version:1,sessionId:'synthetic-session',inputIdentity:'v1:'+'a'.repeat(64),project:'synthetic',provider:'synthetic',model:'synthetic',extractedAt:time,result:{added:1,updated:0,superseded:0,skipped:0},facts:[{uuid:'new-fact',type:'learning',content:'synthetic new fact'}]}}});
 for(const action of ['batch-rebuild','event-backup','remote-backup','paired-sync'] as const){
  const home=join(storage.dir,action),data=join(home,'data','memory');mkdirSync(data,{recursive:true});const dbPath=join(data,'memory.db'),events=join(data,'events');
  if(action==='paired-sync')mkdirSync(dbPath);else{const db=new OwnedDatabase(dbPath);try{createSchema(db);db.run("INSERT INTO facts(uuid,type,project,content,observed_at) VALUES('existing','learning','synthetic','synthetic fixture',?)",[time]);}finally{db.close();}}
  if(action==='batch-rebuild'){mkdirSync(events);writeFileSync(join(events,'events-synthetic.jsonl'),JSON.stringify(wrapper.toJSON())+'\n');}else writeFileSync(events,'Synthetic source fence.');
  const before=action==='paired-sync'?null:sha(readFileSync(dbPath));
  const args=action==='batch-rebuild'?['projections','rebuild','--confirm','--json']:action==='event-backup'?['backup','create','--json']:action==='remote-backup'?['remote','backup','--json']:['sync','--json'];
  const execution=await run(action,[shim,...args],home,home);
  let facts=null;if(action!=='paired-sync'){const db=new OwnedDatabase(dbPath);try{using statement=db.prepare('SELECT uuid FROM facts ORDER BY uuid');facts=statement.all();}finally{db.close();}}
  const after=action==='paired-sync'?null:sha(readFileSync(dbPath)),row={action,execution,facts,databaseBefore:before,databaseAfter:after};report.fixtures.push(row);
  if(action==='batch-rebuild'){assert.equal(execution.exit,0);assert.deepEqual(facts,[{uuid:'new-fact'}]);}else{assert.equal(execution.exit,1);assert.equal(before,after);assert.equal(readFileSync(events,'utf8'),'Synthetic source fence.');}
 }
 await run('dependency-tree',[process.execPath,'pm','ls','--all'],consumer,consumer);
 await run('dependency-audit',[process.execPath,'audit','--json'],consumer,consumer);
 for(const f of packageFiles)assert.equal(sha(readFileSync(join(installedRoot,f.path))),f.sha256);
 for(const f of sourceInputs)assert.equal(sourceHash(readFileSync(f.path,'utf8')),f.sourceHash,f.path);
 report.status='complete';report.inputsUnchanged=true;
 report.limits=['Bounded compatibility probe, not D04 acceptance. Dependency scripts disabled; native embedding/runtime/model and fresh full install remain unverified.','Build uses existing checkout compiler/dependencies but emits only into owned staging. Consumer dependencies resolve afresh without checkout overrides.','One Windows Bun 1.4.1 runtime. No supported-platform, full API/hook/CLI, migration, rollback, quality or final-review acceptance.','No live installation, canonical memory, hook, provider or batch emission changed. Synthetic batch produced only by probe.'];
}catch(error){report.status='failed';report.error=String(error);throw error;}
finally{report.source=readFileSync(import.meta.path,'utf8');writeFileSync('.git/d05-package-consumer.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({status:report.status,error:report.error,artifact:report.artifact?{bytes:report.artifact.bytes,sha256:report.artifact.sha256}:null,fixtures:report.fixtures.map((f:any)=>({action:f.action,exit:f.execution.exit}))}));storage.cleanup();}

