import { strict as assert } from 'node:assert';
import { lstatSync,readFileSync,readdirSync,realpathSync,rmSync,existsSync,writeFileSync } from 'node:fs';
import { join,resolve,relative } from 'node:path';
import { Database } from 'bun:sqlite';
const target=resolve('C:/Users/Destiny/AppData/Local/Temp/memory-d05-compat-qNPjfK'),parent=resolve('C:/Users/Destiny/AppData/Local/Temp');
assert.equal(relative(parent,target),'memory-d05-compat-qNPjfK');assert.equal(realpathSync(target),target);
const marker=join(target,'.memory-test-owner.json'),markerStat=lstatSync(marker);assert(markerStat.isFile()&&!markerStat.isSymbolicLink()&&markerStat.nlink===1);
const owner=JSON.parse(readFileSync(marker,'utf8')),stat=lstatSync(target,{bigint:true});
assert.equal(owner.project,'memory-nexus');assert.equal(owner.id,'22d6439e-b1cc-446b-ac80-f1cb31580153');assert.equal(owner.pid,24936);assert.equal(owner.dir,target);assert.equal(owner.device,stat.dev.toString());assert.equal(owner.inode,stat.ino.toString());assert(stat.isDirectory()&&!stat.isSymbolicLink());
const processCheck=Bun.spawnSync(['powershell.exe','-NoProfile','-NonInteractive','-Command',"$p=@(Get-Process -Id 24936 -ErrorAction SilentlyContinue); $m=@(Get-CimInstance Win32_Process | Where-Object {$_.Name -eq 'memory.exe' -or ($_.Name -eq 'bun.exe' -and $_.CommandLine -like '*sync*--session*')}); if ($p.Count -or $m.Count) { exit 1 }; exit 0"],{stdout:'pipe',stderr:'pipe'});assert.equal(processCheck.exitCode,0,'A possible fixture process remains');
const allowed=['sync-hook-script-test-1790625167714-epxtjhy9kem','sync-hook-script-test-1790625168188-wq1ugwpurgh'];assert.deepEqual(readdirSync(target).sort(),['.memory-test-owner.json',...allowed].sort());
const files:any[]=[];function walk(dir:string){for(const name of readdirSync(dir)){const path=join(dir,name),s=lstatSync(path);assert(!s.isSymbolicLink());if(s.isDirectory())walk(path);else{assert(s.isFile()&&s.nlink===1);files.push({path:relative(target,path),bytes:s.size});}}}walk(target);
const counts=[];for(const name of allowed){const path=join(target,name,'.local','share','memory','memory.db'),db=new Database(path,{readonly:true});try{const sessions=db.query('SELECT COUNT(*) AS count FROM sessions').get() as {count:number},messages=db.query('SELECT COUNT(*) AS count FROM messages_meta').get() as {count:number};assert.equal(sessions.count,0);assert.equal(messages.count,0);counts.push({fixture:name,sessions:sessions.count,messages:messages.count});}finally{db.close();}}
rmSync(target,{recursive:true,force:false,maxRetries:3,retryDelay:100});assert(!existsSync(target));
writeFileSync('.git/d05-retained-cleanup.json',JSON.stringify({recordedAt:new Date().toISOString(),target,owner,files,counts,processCheckExit:processCheck.exitCode,removed:true,source:readFileSync(import.meta.path,'utf8')},null,2)+'\n');console.log('Verified empty synthetic databases and owned fixture removed');

